def number_to_words(n: int) -> str:
    if not isinstance(n, int) or not (0 <= n <= 999999):
        raise ValueError("Number must be an integer between 0 and 999999 inclusive.")

    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def _convert_below_thousand(num: int) -> str:
        if num == 0:
            return ""

        parts = []
        hundreds_digit = num // 100
        remainder = num % 100

        if hundreds_digit > 0:
            parts.append(ones[hundreds_digit] + " hundred")

        if remainder > 0:
            if hundreds_digit > 0:
                parts.append("and")

            if remainder < 20:
                parts.append(ones[remainder])
            else:
                t = remainder // 10
                o = remainder % 10
                if o > 0:
                    parts.append(f"{tens[t]}-{ones[o]}")
                else:
                    parts.append(tens[t])

        return " ".join(parts)

    thousands_part = n // 1000
    remainder_part = n % 1000

    parts = []

    if thousands_part > 0:
        thousands_str = _convert_below_thousand(thousands_part) + " thousand"
        parts.append(thousands_str)

    if remainder_part > 0:
        if thousands_part > 0:
            if remainder_part < 100:
                parts.append("and")
        parts.append(_convert_below_thousand(remainder_part))

    return " ".join(parts)
